const object = (properties, required = [], extra = false) => ({ type: 'object', additionalProperties: extra, properties, ...(required.length ? { required } : {}) });
const timestamp = { type: 'string', format: 'date-time' };
const boolean = { type: 'boolean' };
const integer = { type: 'integer', minimum: 0 };
const revision = { type: 'integer', minimum: 1, maximum: 999999999 };
const reason = text(1000);
const problem = { description: 'Application problem or compatible safe HTTP boundary error. Current authorization is checked before data or replay is returned.', content: { 'application/problem+json': { schema: ref('Problem') }, 'application/json': { schema: ref('RecordSafeHttpError') } } };
