  RecordTimelineEvent: object({ id: text(), type: text(), reportedAt: nullable(timestamp), receivedAt: timestamp, source: text(), actorId: nullable(text()), subjectId: text(), data: { type: 'object', additionalProperties: true } }, ['id', 'type', 'reportedAt', 'receivedAt', 'source', 'actorId', 'subjectId', 'data'], true),
  RecordEvidence: object({ id: text(), type: text(), contentType: text(), byteSize: nullable(integer), sha256: nullable({ type: 'string', pattern: '^[a-f0-9]{64}$' }), state: { type: 'string', enum: ['available', 'pending', 'rejected'] }, receivedAt: timestamp, reportedAt: nullable(timestamp), source: text(), subjectIds: list(text()), original: { const: true } }, ['id', 'type', 'contentType', 'byteSize', 'sha256', 'state', 'receivedAt', 'reportedAt', 'source', 'subjectIds', 'original'], true),
  RecordRequirement: object({ id: text(), subjectId: text(), stage: text(), title: text(), templateVersion: text(), acceptedEvidenceTypes: list(text()), dueAt: nullable(timestamp), gracePeriodMs: integer, status: { type: 'string', enum: ['satisfied', 'missing', 'not_yet_due', 'waived'] }, evidenceIds: list(text()), waiver: nullable(object({ id: text(), reason, actorId: text(), createdAt: timestamp }, ['id', 'reason', 'actorId', 'createdAt'])) }, ['id', 'subjectId', 'stage', 'title', 'templateVersion', 'acceptedEvidenceTypes', 'dueAt', 'gracePeriodMs', 'status', 'evidenceIds', 'waiver'], true),
  RecordIssue: object({ id: text(), proofId: text(), category: text(), severity: { type: 'string', enum: ['info', 'warning', 'critical'] }, title: text(), subjectId: text(), ruleVersion: text(), comparedSources: {}, status: { type: 'string', enum: ['open', 'acknowledged', 'resolved'] }, createdAt: timestamp, updatedAt: timestamp, actions: list(object({ id: text(), action: text(), reason, actorId: text(), createdAt: timestamp }, ['id', 'action', 'reason', 'actorId', 'createdAt'])) }, ['id', 'proofId', 'category', 'severity', 'title', 'subjectId', 'ruleVersion', 'comparedSources', 'status', 'createdAt', 'updatedAt', 'actions'], true),
  RecordDetail: object({ schema: { const: 'packproof.records/v1' }, record: ref('RecordSummary'), timeline: list(ref('RecordTimelineEvent')), evidence: list(ref('RecordEvidence')), timelineNextCursor: nullable(text(2000)), evidenceNextCursor: nullable(text(2000)), requirements: list(ref('RecordRequirement')), issues: list(ref('RecordIssue')), relationships: list({ type: 'object', additionalProperties: true }), assurance: object({ coreManifest: { type: 'string', enum: ['present', 'absent'] }, operationalView: { const: 'not_a_signed_snapshot' }, physicalCondition: { const: 'not_established' }, explanation: text(2000) }, ['coreManifest', 'operationalView', 'physicalCondition', 'explanation']), sourceHealth: object({ state: { type: 'string', enum: ['not_applicable', 'freshness_unknown'] }, message: text(2000) }, ['state', 'message']), capabilities: object({ edit: boolean, review: boolean, waive: boolean, export: boolean, downloadOriginal: boolean, capture: boolean, operationalSnapshots: { const: false } }, ['edit', 'review', 'waive', 'export', 'downloadOriginal', 'capture', 'operationalSnapshots']) }, ['schema', 'record', 'timeline', 'evidence', 'timelineNextCursor', 'evidenceNextCursor', 'requirements', 'issues', 'relationships', 'assurance', 'sourceHealth', 'capabilities'], true),
  RecordTimelinePage: object({ timeline: list(ref('RecordTimelineEvent')), nextCursor: nullable(text(2000)), hasMore: boolean }, ['timeline', 'nextCursor', 'hasMore']),
  RecordEvidencePage: object({ evidence: list(ref('RecordEvidence')), nextCursor: nullable(text(2000)), hasMore: boolean }, ['evidence', 'nextCursor', 'hasMore']),
  RecordPatch: { ...object({ title: nullable(text()), reference: nullable(text()), locationId: nullable(text()), reason }, ['reason']), minProperties: 2 },
  RecordReason: object({ reason }, ['reason']),
  RecordAmendment: object({ supersedesId: text(), assertion: { type: 'object', additionalProperties: true }, reason }, ['supersedesId', 'assertion', 'reason']),
  RecordEntityInput: object({ kind: { type: 'string', enum: ['shipment', 'stop', 'package', 'pallet', 'item', 'return'] }, externalReference: text(), parentId: text(), attributes: { type: 'object', additionalProperties: true }, supersedesId: text(), reason }, ['kind', 'reason']),
  RecordEvidenceLinkInput: object({ evidenceId: text(), subjectId: text(), reason }, ['evidenceId', 'subjectId', 'reason']),
  RecordCommandReceipt: object({ proofId: text(), revision }, ['proofId', 'revision'], true),
  RecordCsvMapping: object(Object.fromEntries(['shipmentReference', 'itemTitle', 'quantity', 'trackingNumber', 'carrier', 'shippedAt', 'locationId'].map(name => [name, text(10000)]))),
  RecordCsvPreviewInput: object({ organizationId: text(), environment: { type: 'string', enum: ['sandbox', 'live'] }, csv: { type: 'string', maxLength: 2097152 }, mapping: ref('RecordCsvMapping'), timeZone: text(100), sourceName: text(80) }, ['organizationId', 'environment', 'csv', 'timeZone']),
  RecordCsvCommitInput: object({ previewVersion: { type: 'string', pattern: '^[a-f0-9]{64}$' }, importValidRows: boolean }, ['previewVersion', 'importValidRows']),
  RecordCsvRow: object({ rowNumber: { type: 'integer', minimum: 2 }, status: { type: 'string', enum: ['valid', 'invalid', 'duplicate', 'ambiguous', 'imported', 'failed'] }, values: { type: 'object', additionalProperties: { type: 'string' } }, errors: list({ type: 'string' }), normalized: nullable({ type: 'object', additionalProperties: true }), payloadSha256: nullable({ type: 'string', pattern: '^[a-f0-9]{64}$' }), proofId: text() }, ['rowNumber', 'status', 'values', 'errors', 'normalized', 'payloadSha256'], true),
  RecordImport: object({ id: text(), previewVersion: text(), state: { type: 'string', enum: ['previewed', 'queued', 'running', 'succeeded', 'partially_succeeded', 'failed', 'action_needed'] }, organizationId: text(), environment: { type: 'string', enum: ['sandbox', 'live'] }, sourceName: text(80), timeZone: text(100), mappingVersion: { const: 'packproof.csv-mapping/v1' }, mapping: ref('RecordCsvMapping'), headers: list({ type: 'string' }), delimiter: { type: 'string', enum: [',', ';', '\t'] }, encoding: { const: 'UTF-8' }, receivedAt: timestamp, updatedAt: timestamp, original: object({ sha256: { type: 'string', pattern: '^[a-f0-9]{64}$' }, byteSize: integer, versionBound: boolean }, ['sha256', 'byteSize', 'versionBound']), counts: object(Object.fromEntries(['valid', 'invalid', 'duplicate', 'ambiguous', 'imported', 'failed'].map(state => [state, integer])), ['valid', 'invalid', 'duplicate', 'ambiguous', 'imported', 'failed']), rows: list(ref('RecordCsvRow')), correctionsCsv: { type: 'string' }, recordIds: list(text()), lastErrorCode: nullable(text()), syncStatus: { const: 'not_applicable' }, message: text(2000) }, ['id', 'previewVersion', 'state', 'organizationId', 'environment', 'sourceName', 'timeZone', 'mappingVersion', 'mapping', 'headers', 'delimiter', 'encoding', 'receivedAt', 'updatedAt', 'original', 'counts', 'rows', 'correctionsCsv', 'recordIds', 'lastErrorCode', 'syncStatus', 'message'], true),
