Object.assign(api.components.schemas, schemas);
api['x-packproof-records-profile'] = { version: 'packproof.records/v1', generatedBy: 'scripts/generate-records-openapi.mjs', nodeSdk: 'packages/partner-sdk-typescript', pythonSdk: 'packages/partner-sdk-python', webhookProfile: 'PackProof-Signature t/v1 HMAC-SHA256 (existing compatible wire format)' };
api.components.securitySchemes.PersonSession.description = 'First-party authenticated person with current organization membership. Organization administration requires recent authentication; service principals do not acquire human capture, waiver or personal attestation authority.';

function endpoint(method, route, { summary, description, response, input, human = false, parameters = [], command = false, statuses = [200], responseHeaders = {} }) {
  const op = {
    operationId: `${method}_${route.replace(/[^a-zA-Z0-9]/g, '_')}`,
    summary,
    description,
    'x-packproof-generated-records': true,
    security: [{ [human ? 'PersonSession' : 'PartnerCredential']: [] }],
    parameters: [...(human ? [] : selectors), ...parameters, ...(command ? commandHeaders : [])],
    responses: Object.fromEntries(statuses.map(status => [String(status), { ...jsonResponse(response), ...(Object.keys(responseHeaders).length ? { headers: responseHeaders } : {}) }])),
  };
  for (const status of [400, 401, 403, 404, 409, 410, 412, 413, 415, 428, 429, 500, 503]) op.responses[status] = problem;
  if (input) op.requestBody = { required: true, content: { 'application/json': { schema: input } } };
  api.paths[route] ??= {};
  api.paths[route][method] = op;
}

const rootPath = '/v1/partner/proofs/{proofId}';
const readDescription = 'Required scope: proofs:read. Uses current merchant/environment/delegation/record/location authorization. Existing Proof identity and cryptographic state remain unchanged. Service credentials do not receive human attestation or waiver authority.';
for (const [suffix, summary, response] of [
  ['/record', 'Read the operational record view', ref('RecordDetail')],
  ['/timeline', 'Read source-attributed record history', ref('RecordTimelinePage')],
  ['/evidence', 'Read evidence metadata and subject associations', ref('RecordEvidencePage')],
  ['/requirements', 'Read versioned evidence expectations and due states', object({ requirements: list(ref('RecordRequirement')) }, ['requirements'])],
]) endpoint('get', rootPath + suffix, { summary, description: readDescription + (['/timeline', '/evidence'].includes(suffix) ? ' Child cursors bind organization, environment, Proof, caller and page size; changing any of those requires a fresh listing. Default 50, maximum 100 items.' : ''), response, parameters: [pathId('proofId'), ...(['/timeline', '/evidence'].includes(suffix) ? childPage : [])] });

const mutationDescription = 'Required scope: proofs:write. Current record authorization, stable command idempotency and the expected operational revision are checked transactionally. A stale revision returns 412; missing/invalid revision returns 428. Corrections append history and cannot mutate historical signed bytes. Revocation is checked again before replay or response. Partner location changes are restricted by the existing role policy.';
for (const [method, suffix, summary, input] of [
  ['patch', '', 'Amend permitted operational metadata', ref('RecordPatch')],
  ['post', '/close', 'Close an operational record', ref('RecordReason')],
  ['post', '/reopen', 'Reopen an operational record', ref('RecordReason')],
  ['post', '/amendments', 'Append a superseding source assertion', ref('RecordAmendment')],
  ['post', '/entities', 'Append a shipment, stop, handling unit, item or return relationship', ref('RecordEntityInput')],
  ['post', '/evidence-links', 'Append a traceable evidence-to-subject association', ref('RecordEvidenceLinkInput')],
]) endpoint(method, rootPath + suffix, { summary, description: mutationDescription + (suffix === '/close' ? ' Closing requires all applicable requirements satisfied or explicitly waived and all issues resolved; operational closure is separate from signing.' : ''), response: ref('RecordCommandReceipt'), input, parameters: [pathId('proofId')], command: true, responseHeaders: { 'Idempotency-Replayed': { schema: boolean, description: 'True when the original logical command result was returned.' } } });

const importPath = '/me/records/imports';
endpoint('post', importPath + '/preview', { human: true, summary: 'Preserve and validate an entire spreadsheet before import', description: 'Human-session route; not a partner service-credential endpoint. Requires current organization write access, explicit source time zone and active feature/entitlement. Preserves original UTF-8 bytes, digest, exact object version in production, mapping version and row outcomes. Current caps: 2 MiB, 1000 data rows, 50 columns, 10000 characters per cell. CSV source identities are scoped by organization, environment, source name and shipment reference.', input: ref('RecordCsvPreviewInput'), response: ref('RecordImport'), statuses: [201] });
endpoint('get', importPath + '/{importId}', { human: true, summary: 'Read a durable import receipt and row outcomes', description: 'Rechecks current workspace and every represented location before returning rows, counts or correction output. Operator access is restricted to imports they created or committed. A one-time CSV never becomes a recurring sync.', response: ref('RecordImport'), parameters: [pathId('importId')] });
endpoint('post', importPath + '/{importId}/commit', { human: true, summary: 'Commit the exact reviewed import preview', description: 'Commit is idempotent by durable import identity and exact previewVersion. Explicit importValidRows confirmation controls partial acceptance. Returns 202 only after the durable queued receipt commits, or 200 for an already completed import. Poll the returned Location. Previous successful rows survive retries. Changed source details require review and append-only correction.', input: ref('RecordCsvCommitInput'), response: ref('RecordImport'), parameters: [pathId('importId')], statuses: [200, 202], responseHeaders: { Location: { schema: { type: 'string' }, description: 'API-relative URL of the durable import receipt.' } } });
endpoint('get', importPath + '/limits', { human: true, summary: 'Read effective spreadsheet import caps', description: 'Authenticated human feature-gated route. Effective validated caps are smaller than the preliminary plan targets.', response: object({ limits: object({ bytes: { const: 2097152 }, rows: { const: 1000 }, columns: { const: 50 }, cellLength: { const: 10000 } }, ['bytes', 'rows', 'columns', 'cellLength']), encoding: { const: 'UTF-8' }, supportedDelimiters: list({ type: 'string', enum: [',', ';', '\t'] }), sourceTimeZoneRequired: { const: true } }, ['limits', 'encoding', 'supportedDelimiters', 'sourceTimeZoneRequired']) });
for (const [route, summary] of [[importPath + '/template.csv', 'Download a shipment CSV template'], [importPath + '/{importId}/corrections.csv', 'Download formula-safe row corrections']]) {
  endpoint('get', route, { human: true, summary, description: 'Treats spreadsheet formulas and markup as data. Correction exports escape formula-leading values. Private rows require current workspace and location authorization.', response: { type: 'string' }, parameters: route.includes('{importId}') ? [pathId('importId')] : [] });
  api.paths[route].get.responses['200'].content = { 'text/csv': { schema: { type: 'string' } } };
}

const workspaceFields = { organizationId: text(), environment: { type: 'string', enum: ['sandbox', 'live'] } };
const role = { type: 'string', enum: ['OWNER', 'ADMIN', 'OPERATOR', 'REVIEWER'] };
